using EEMS.Modules.Identity.Infrastructure;
using EEMS.Modules.Reporting.Infrastructure;
using EEMS.Modules.Teams.Infrastructure;
using EEMS.SharedKernel.Tenancy;
using Microsoft.EntityFrameworkCore;
namespace EEMS.Api.Audit;

public sealed class AuditNotificationService(ReportingDbContext db,IdentityDbContext identity,TeamsDbContext teamsDb,ITenantContext tenant)
{
 public async Task<AuditPage> GetAudit(string? search,int page,int pageSize,CancellationToken ct){var query=db.AuditLogs.Where(x=>x.TenantId==tenant.TenantId);if(!string.IsNullOrWhiteSpace(search)){var term=$"%{search.Trim()}%";query=query.Where(x=>EF.Functions.ILike(x.Action,term)||EF.Functions.ILike(x.EntityType,term)||EF.Functions.ILike(x.EntityId,term)||EF.Functions.ILike(x.CorrelationId,term));}var count=await query.CountAsync(ct);var rows=await query.OrderByDescending(x=>x.OccurredAtUtc).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct);var users=await identity.Users.Where(x=>rows.Select(r=>r.ActorUserId).Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.DisplayName,ct);return new(rows.Select(x=>new AuditEntry(x.Id,x.ActorUserId,users.GetValueOrDefault(x.ActorUserId,"Unknown user"),x.Action,x.EntityType,x.EntityId,x.CorrelationId,x.MetadataJson,x.OccurredAtUtc)).ToArray(),count,page,pageSize);}
 public async Task<NotificationFeed> GetNotifications(CancellationToken ct){var tenantId=tenant.TenantId;var security=await db.SecurityEvents.Where(x=>x.TenantId==tenantId).OrderByDescending(x=>x.OccurredAtUtc).Take(30).Select(x=>new NotificationItem(x.Id.ToString(),"security",x.EventType,x.Detail,x.Source,x.OccurredAtUtc,true,null,"HIGH")).ToListAsync(ct);var outbox=await db.Outbox.Where(x=>x.TenantId==tenantId&&x.ProcessedAtUtc==null).OrderByDescending(x=>x.OccurredAtUtc).Take(30).Select(x=>new NotificationItem(x.Id.ToString(),"operation",x.MessageType,x.PayloadJson,x.CorrelationId,x.OccurredAtUtc,false,null,"NORMAL")).ToListAsync(ct);var workforce=await GetWorkforceAlerts(tenantId,ct);return new(workforce.Concat(security).Concat(outbox).OrderByDescending(x=>x.OccurredAtUtc).Take(75).ToArray(),outbox.Count+workforce.Count);}
 private async Task<List<NotificationItem>> GetWorkforceAlerts(Guid tenantId,CancellationToken ct){var now=DateTimeOffset.UtcNow;var today=DateOnly.FromDateTime(now.UtcDateTime);var occurred=new DateTimeOffset(now.Year,now.Month,now.Day,0,0,0,TimeSpan.Zero);var teams=await teamsDb.Teams.Where(x=>x.TenantId==tenantId&&x.IsActive).ToListAsync(ct);var teamIds=teams.Select(x=>x.Id).ToArray();var members=await teamsDb.FieldMembers.Where(x=>x.TenantId==tenantId&&teamIds.Contains(x.TeamId)&&x.IsActive).ToListAsync(ct);var attended=await teamsDb.FieldMemberAttendances.Where(x=>x.TenantId==tenantId&&teamIds.Contains(x.TeamId)&&x.AttendanceDate==today).Select(x=>x.MemberId).ToListAsync(ct);var terminal=await teamsDb.TaskStates.Where(x=>x.IsActive&&x.IsTerminal).Select(x=>x.Id).ToListAsync(ct);var work=await teamsDb.MemberWorkAssignments.Where(x=>x.TenantId==tenantId&&teamIds.Contains(x.TeamId)).ToListAsync(ct);var alerts=new List<NotificationItem>();foreach(var team in teams){var url=$"/elections/{team.ElectionId}/workforce/teams/{team.Id}";var teamMembers=members.Where(x=>x.TeamId==team.Id).ToList();var teamWork=work.Where(x=>x.TeamId==team.Id).ToList();var attendancePending=teamMembers.Count(x=>!attended.Contains(x.Id));var overdue=teamWork.Count(x=>!terminal.Contains(x.StateId)&&x.DueAtUtc<now);var verification=teamWork.Count(x=>terminal.Contains(x.StateId)&&x.VerifiedAtUtc==null);if(team.LeaderUserId is null)alerts.Add(new($"leader-{team.Id}","workforce","Team leader missing",$"{team.Name} has no accountable team leader assigned.",team.Name,occurred,false,url,"HIGH"));if(attendancePending>0)alerts.Add(new($"attendance-{today:yyyyMMdd}-{team.Id}","workforce","Attendance pending",$"{attendancePending} active member(s) in {team.Name} have no attendance record today.",team.Name,occurred,false,url,"NORMAL"));if(overdue>0)alerts.Add(new($"overdue-{team.Id}","workforce","Overdue field work",$"{overdue} work item(s) in {team.Name} are past their due date.",team.Name,now,false,url,"HIGH"));if(verification>0)alerts.Add(new($"verify-{team.Id}","workforce","Work verification pending",$"{verification} completed work item(s) in {team.Name} require verification.",team.Name,now,false,url,"NORMAL"));}return alerts;}
}
public sealed record AuditPage(IReadOnlyList<AuditEntry> Items,int TotalCount,int Page,int PageSize);public sealed record AuditEntry(long AuditLogId,Guid ActorUserId,string ActorName,string Action,string EntityType,string EntityId,string CorrelationId,string MetadataJson,DateTimeOffset OccurredAtUtc);public sealed record NotificationFeed(IReadOnlyList<NotificationItem> Items,int UnreadCount);public sealed record NotificationItem(string Id,string Category,string Title,string Message,string Source,DateTimeOffset OccurredAtUtc,bool IsSecurityEvent,string? ActionUrl,string Severity);
